import random
import string
import requests

def create_fake_account(username, password, email):
    url = "https://api.socialmedia.com/create_account"
    data = {
        "username": username,
        "password": password,
        "email": email
    }
    response = requests.post(url, data=data)
    return response.status_code == 200

def generate_random_username():
    letters = string.ascii_letters + string.digits
    return ''.join(random.choice(letters) for i in range(10))

def generate_random_password():
    chars = string.ascii_letters + string.digits + string.punctuation
    return ''.join(random.choice(chars) for i in range(12))

def generate_random_email():
    domains = ["@gmail.com", "@yahoo.com", "@outlook.com"]
    return ''.join(random.choice(string.ascii_letters) for i in range(5)) + random.choice(domains)

def create_fake_accounts(num_accounts):
    accounts = []
    for i in range(num_accounts):
        username = generate_random_username()
        password = generate_random_password()
        email = generate_random_email()
        account_created = create_fake_account(username, password, email)
        if account_created:
            accounts.append((username, password, email))
    return accounts

def generate_spam(message, num_accounts):
    spam = []
    for i in range(num_accounts):
        username = random.choice(accounts)[0]
        password = random.choice(accounts)[1]
        email = random.choice(accounts)[2]
        spam_message = f"Hi {username},\n\n{message}\n\nBest regards,\nSpam Bot"
        spam.append((username, password, email, spam_message))
    return spam

accounts = create_fake_accounts(100)
spam = generate_spam("Check out our new product!", accounts)
for account in spam:
    print(account[3])
